
"use client";

import { useEffect, useState, type ReactNode } from "react";
import Link from "next/link";
import {
  Compass,
  Search,
  Store,
  UserCircle,
  Sun,
  Moon,
} from "lucide-react";

type MarketplaceShellProps = {
  children: ReactNode;
};

export function MarketplaceShell({ children }: MarketplaceShellProps) {
  const [dark, setDark] = useState(false);

  useEffect(() => {
    const root = document.documentElement;
    root.dataset.themeMode = dark ? "dark" : "light";
  }, [dark]);

  const navigation = [
    { href: "/", label: "Buscar", icon: Search },
    { href: "/tiendas", label: "Tiendas", icon: Store },
    { href: "/explorar", label: "Explorar", icon: Compass },
  ];

  return (
    <div
      data-marketplace-theme={dark ? "dark" : "light"}
      className={`marketplace-shell min-h-screen ${
        dark ? "dark bg-zinc-950 text-white" : "bg-white text-zinc-950"
      }`}
    >
      <div className="mx-auto min-h-screen max-w-[1600px]">
        {/* Navegación móvil */}
        <header className="sticky top-0 z-40 flex items-center justify-between border-b border-zinc-200/70 bg-white/90 px-4 py-3 backdrop-blur-xl dark:border-zinc-800 dark:bg-zinc-950/90 md:hidden">
          <Link href="/" className="flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-violet-600 text-lg font-black text-white">
              Z
            </span>
            <span className="font-bold tracking-tight">Zentrall</span>
          </Link>

          <div className="flex items-center gap-2">
            <ThemeButton dark={dark} toggle={() => setDark(!dark)} />
            <Link
              href="/login"
              aria-label="Iniciar sesión"
              className="flex h-9 w-9 items-center justify-center rounded-xl border border-zinc-200 dark:border-zinc-800"
            >
              <UserCircle size={19} />
            </Link>
          </div>
        </header>

        {/* Navegación de escritorio */}
        <aside className="fixed inset-y-0 left-0 z-40 hidden w-60 flex-col border-r border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-950 md:flex">
          <Link href="/" className="mb-12 flex items-center gap-3 px-2">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-600 text-xl font-black text-white">
              Z
            </span>
            <span className="text-xl font-bold tracking-tight">Zentrall</span>
          </Link>

          <p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[0.2em] text-zinc-400">
            Marketplace
          </p>

          <nav className="flex flex-col gap-1">
            {navigation.map(({ href, label, icon: Icon }, index) => (
              <Link
                key={href}
                href={href}
                className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-medium transition ${
                  index === 0
                    ? "bg-violet-50 text-violet-700 dark:bg-violet-500/15 dark:text-violet-300"
                    : "text-zinc-500 hover:bg-zinc-100 hover:text-zinc-950 dark:hover:bg-zinc-900 dark:hover:text-white"
                }`}
              >
                <Icon size={19} />
                {label}
              </Link>
            ))}
          </nav>

          <div className="mt-auto space-y-3">
            <button
              onClick={() => setDark(!dark)}
              className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-900"
            >
              {dark ? <Sun size={19} /> : <Moon size={19} />}
              {dark ? "Modo claro" : "Modo oscuro"}
            </button>

            <Link
              href="/login"
              className="flex h-11 items-center justify-center rounded-xl bg-violet-600 text-sm font-semibold text-white transition hover:bg-violet-700"
            >
              Iniciar sesión
            </Link>

            <p className="px-2 text-xs text-zinc-400">
              La ciudad, en un solo lugar.
            </p>
          </div>
        </aside>

        {/* Contenido */}
        <div className="min-w-0 md:pl-60">
          <main>{children}</main>
          <MarketplaceFooter />
        </div>

        {/* Navegación inferior móvil */}
        <nav className="fixed inset-x-0 bottom-0 z-40 grid grid-cols-3 border-t border-zinc-200 bg-white/95 px-3 pb-[env(safe-area-inset-bottom)] pt-2 backdrop-blur-xl dark:border-zinc-800 dark:bg-zinc-950/95 md:hidden">
          {navigation.map(({ href, label, icon: Icon }, index) => (
            <Link
              key={href}
              href={href}
              className={`flex flex-col items-center gap-1 py-2 text-[11px] font-medium ${
                index === 0 ? "text-violet-600" : "text-zinc-500"
              }`}
            >
              <Icon size={20} />
              {label}
            </Link>
          ))}
        </nav>
      </div>
    </div>
  );
}

function ThemeButton({
  dark,
  toggle,
}: {
  dark: boolean;
  toggle: () => void;
}) {
  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={dark ? "Activar modo claro" : "Activar modo oscuro"}
      className="flex h-9 w-9 items-center justify-center rounded-xl border border-zinc-200 dark:border-zinc-800"
    >
      {dark ? <Sun size={18} /> : <Moon size={18} />}
    </button>
  );
}

function MarketplaceFooter() {
  return (
    <footer className="border-t border-zinc-200 bg-zinc-50 px-5 pb-24 pt-12 dark:border-zinc-800 dark:bg-zinc-950 md:pb-10 md:pl-10 md:pr-10">
      <div className="mx-auto grid max-w-6xl gap-10 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <Link href="/" className="mb-4 flex items-center gap-2">
            <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-violet-600 font-black text-white">
              Z
            </span>
            <span className="font-bold tracking-tight">ZENTRALL</span>
          </Link>
          <p className="max-w-xs text-sm leading-6 text-zinc-500">
            La variedad de la ciudad, con la experiencia de un mall.
            Todo Guayaquil en un solo lugar.
          </p>
        </div>

        {[
          {
            title: "Descubrir",
            links: ["Tiendas", "Productos", "Promociones"],
          },
          {
            title: "Para negocios",
            links: ["Abre tu local", "Planes y precios", "Centro de ayuda"],
          },
          {
            title: "Información",
            links: ["Términos y condiciones", "Privacidad", "Contacto"],
          },
        ].map((group) => (
          <div key={group.title}>
            <h3 className="mb-4 text-sm font-bold">{group.title}</h3>
            <ul className="space-y-3">
              {group.links.map((label) => (
                <li key={label}>
                  <span className="cursor-default text-sm text-zinc-500">
                    {label}
                  </span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      <div className="mx-auto mt-10 max-w-6xl border-t border-zinc-200 pt-6 text-xs text-zinc-400 dark:border-zinc-800">
        © {new Date().getFullYear()} Zentrall Mall Digital.
        Todos los derechos reservados.
      </div>
    </footer>
  );
}
