"use client";

import { useState } from "react";
import Link from "next/link";
import { Lobster_Two } from "next/font/google";
import { ArrowRight, Menu, ShoppingBag, Store, X } from "lucide-react";

const script = Lobster_Two({
  subsets: ["latin"],
  weight: ["400", "700"],
  style: ["normal", "italic"],
});

/**
 * Cambia esto por la foto real del hero (por ejemplo "/hero.jpg" dentro de /public).
 * Mientras sea null se usa un fondo con degradados cálidos.
 */
const HERO_IMAGE: string | null = null;

const navLinks = [
  { label: "Inicio", href: "/" },
  { label: "Explorar", href: "/explorar" },
  { label: "Tiendas", href: "/tiendas" },
  { label: "Rutas", href: "/rutas" },
  { label: "Ofertas", href: "/explorar" },
];

export function MarketplaceHomePage() {
  const [menuOpen, setMenuOpen] = useState(false);

  return (
    <div className="min-w-0">
      <section className="relative isolate overflow-hidden bg-[#2b1a12] text-white">
        {/* Fondo */}
        <div
          aria-hidden
          className="absolute inset-0 -z-10 bg-cover bg-center"
          style={
            HERO_IMAGE
              ? { backgroundImage: `url(${HERO_IMAGE})` }
              : {
                  backgroundImage:
                    "radial-gradient(circle at 75% 30%, rgba(214,160,110,0.55), transparent 45%), radial-gradient(circle at 15% 80%, rgba(120,70,40,0.6), transparent 50%), linear-gradient(135deg, #3a2318 0%, #1f130d 100%)",
                }
          }
        />
        {/* Oscurecedor para legibilidad */}
        <div
          aria-hidden
          className="absolute inset-0 -z-10 bg-gradient-to-b from-black/55 via-black/20 to-black/50"
        />

        {/* Topbar */}
        <header className="relative z-20 mx-auto flex max-w-6xl items-center justify-between px-5 py-5 md:px-10">
          <Link
            href="/"
            className={`${script.className} text-3xl leading-none tracking-wide`}
          >
            Zentrall
          </Link>

          <nav className="hidden items-center gap-8 text-xs font-medium md:flex">
            {navLinks.map((link, index) => (
              <Link
                key={link.label}
                href={link.href}
                className={`border-b pb-1 transition hover:border-white ${
                  index === 0
                    ? "border-white"
                    : "border-transparent text-white/80"
                }`}
              >
                {link.label}
              </Link>
            ))}
          </nav>

          <div className="hidden items-center gap-3 md:flex">
            <Link
              href="/login"
              className="flex h-9 items-center gap-2 rounded-full border border-white/40 bg-white/10 px-4 text-xs font-semibold backdrop-blur transition hover:bg-white/20"
            >
              <ShoppingBag size={14} /> Ingresar
            </Link>
            <Link
              href="/login"
              className="flex h-9 items-center gap-2 rounded-full border border-amber-200/60 bg-black/30 px-4 text-xs font-semibold backdrop-blur transition hover:bg-black/50"
            >
              <Store size={14} /> Mi tienda
            </Link>
          </div>

          <button
            type="button"
            aria-label={menuOpen ? "Cerrar menú" : "Abrir menú"}
            onClick={() => setMenuOpen((open) => !open)}
            className="flex h-10 w-10 items-center justify-center rounded-full border border-white/30 bg-white/10 backdrop-blur md:hidden"
          >
            {menuOpen ? <X size={18} /> : <Menu size={18} />}
          </button>
        </header>

        {/* Menú móvil */}
        {menuOpen && (
          <div className="relative z-20 mx-5 mb-2 flex flex-col gap-1 rounded-2xl border border-white/20 bg-black/60 p-3 backdrop-blur md:hidden">
            {navLinks.map((link) => (
              <Link
                key={link.label}
                href={link.href}
                onClick={() => setMenuOpen(false)}
                className="rounded-xl px-4 py-3 text-sm font-medium transition hover:bg-white/10"
              >
                {link.label}
              </Link>
            ))}
            <Link
              href="/login"
              onClick={() => setMenuOpen(false)}
              className="mt-1 rounded-xl bg-white px-4 py-3 text-center text-sm font-semibold text-[#3a2318]"
            >
              Ingresar
            </Link>
          </div>
        )}

        {/* Contenido del hero */}
        <div className="relative z-10 mx-auto max-w-6xl px-5 pb-48 pt-16 md:px-10 md:pb-64 md:pt-24">
          <h1
            className={`${script.className} max-w-3xl text-5xl leading-[1.05] drop-shadow-[0_4px_18px_rgba(0,0,0,0.5)] sm:text-6xl lg:text-7xl`}
          >
            Descubre lo mejor,
            <span className="block">hecho con amor.</span>
          </h1>

          <Link
            href="/explorar"
            className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#4a3022]/90 px-6 py-3 text-sm font-semibold shadow-lg backdrop-blur transition hover:bg-[#5d3d2b]"
          >
            Explorar ahora <ArrowRight size={16} />
          </Link>
        </div>

        {/* Borde líquido inferior */}
        <svg
          aria-hidden
          viewBox="0 0 1440 160"
          preserveAspectRatio="none"
          className="absolute inset-x-0 bottom-0 z-10 block h-24 w-full md:h-36"
        >
          <path
            d="M0,96 C120,140 260,150 400,120 C560,86 640,40 800,52 C960,64 1060,128 1220,132 C1320,134 1390,112 1440,92 L1440,160 L0,160 Z"
            style={{ fill: "var(--background, #f3f4f8)" }}
          />
        </svg>
      </section>
    </div>
  );
}